from collections import deque
b=data['board']
walk={(r,c) for r in range(11) for c in range(11) if b[6+5*r][6+5*c] in (5,10)}
marks=[(r,c) for r in range(11) for c in range(11) if b[6+5*r][6+5*c]==10]
print('marks',marks,'walk rows',[[c for c in range(11) if (r,c) in walk] for r in range(11)])
def move(p,a):
    ps=list(p)
    if a in (1,2):
        dr=-1 if a==1 else 1
        ps=[(r+dr,c) if (r+dr,c) in walk else (r,c) for r,c in ps]
    else:
        dc=-1 if a==3 else 1
        q=(ps[0][0],ps[0][1]+dc); ps[0]=q if q in walk else ps[0]
        q=(ps[1][0],ps[1][1]-dc); ps[1]=q if q in walk else ps[1]
    return tuple(sorted(ps))
start=tuple(sorted(marks)); q=deque([start]); prev={start:None}
while q:
    p=q.popleft()
    if p[0]==p[1]: break
    for a in (1,2,3,4):
        n=move(p,a)
        if n not in prev: prev[n]=(p,a); q.append(n)
path=[]
while prev[p] is not None: p0,a=prev[p];path.append(a);p=p0
print('path',path[::-1],len(path))

